package org.retrobridge.play2012;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.widget.*;import org.json.*;import java.io.*;import java.security.*;
/** Owner-selected downloads use Android's visible installer after package/hash/signature checks. */
public final class PixelInstall extends Activity {
 static String hash(byte[] data)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(data))s.append(String.format(java.util.Locale.US,"%02x",b&255));return s.toString();}
 static String hash(File file)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");FileInputStream in=new FileInputStream(file);try{byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}finally{in.close();}StringBuilder s=new StringBuilder();for(byte b:digest.digest())s.append(String.format(java.util.Locale.US,"%02x",b&255));return s.toString();}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);setTitle("Google Play");final TextView text=new TextView(this);text.setText("Downloading…");text.setPadding(30,40,30,30);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.addView(text);final ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);layout.addView(bar);setContentView(layout);new Thread(new Runnable(){public void run(){try{
  String pkg=getIntent().getStringExtra("package");final JSONObject item=PixelCatalog.find(pkg);final long total=item.getLong("size");File dir=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"Galaxy Store");dir.mkdirs();final File f=new File(dir,pkg+"-"+item.getInt("versionCode")+".apk");File part=new File(dir,f.getName()+".part");
  try{PixelCatalog.download(pkg,part,total,new PixelCatalog.Progress(){int last=-1;public void update(final int count)throws IOException{if(isFinishing())throw new IOException("Download cancelled");final int percent=(int)(100L*count/total);if(percent==last)return;last=percent;runOnUiThread(new Runnable(){public void run(){bar.setProgress(percent);text.setText("Downloading... "+percent+"%");}});}});
   if(part.length()!=total||!hash(part).equals(item.getString("sha256")))throw new IOException("Download checksum mismatch");PackageInfo pi=getPackageManager().getPackageArchiveInfo(part.toString(),PackageManager.GET_SIGNATURES);if(pi==null||!pkg.equals(pi.packageName)||pi.versionCode!=item.getInt("versionCode")||pi.signatures==null||pi.signatures.length!=1||!hash(pi.signatures[0].toByteArray()).equals(item.getString("signerSha256")))throw new IOException("Download signature mismatch");if(f.exists()&&!f.delete())throw new IOException("Cannot replace installer");if(!part.renameTo(f))throw new IOException("Cannot save installer");
  }finally{part.delete();}
  runOnUiThread(new Runnable(){public void run(){if(isFinishing())return;Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.fromFile(f),"application/vnd.android.package-archive");startActivityForResult(i,1);}});
 }catch(final Exception e){runOnUiThread(new Runnable(){public void run(){text.setText("Download unavailable. Check the Pixel connection and try again.");}});}}},"Catalog download").start();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);finish();}
}
